-- Phase 5 negative suite. Fictional fixtures and all effects roll back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table plan_tap_results(result text);
grant select,insert on plan_tap_results to authenticated,anon;
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
reset role;
-- Simulate the clock reaching due time within the rollback transaction.
update public.plan_reminders set due_at=now()-interval '1 minute' where plan_id='52000000-0000-4000-8000-000000000001';
select private.deliver_due_plan_reminders(100);
select private.deliver_due_plan_reminders(100);
delete from public.plan_reminders where plan_id='52000000-0000-4000-8000-000000000001';
update public.notification_preferences set plans_enabled=false where user_id='50000000-0000-4000-8000-000000000002';
select private.deliver_due_plan_reminders(100);
delete from public.plan_reminders where plan_id='52000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select public.mutate_plan(jsonb_build_object('planId','52000000-0000-4000-8000-000000000001','version',(select version from public.plans where id='52000000-0000-4000-8000-000000000001'),'operation','status','status','cancelled'));
update public.plans set status='completed',completed_by='50000000-0000-4000-8000-000000000001',completed_at=now() where id='52000000-0000-4000-8000-000000000001';
reset role;
-- A failing delivery is isolated, backs off, and stops after five attempts.
update public.plans set status='planned',completed_by=null,completed_at=null where id='52000000-0000-4000-8000-000000000001';
delete from public.plan_reminders where plan_id='52000000-0000-4000-8000-000000000001';
create function pg_temp.reject_fixture_notification() returns trigger language plpgsql as $fail$ begin if new.target_id='52000000-0000-4000-8000-000000000001'::uuid then raise exception 'Synthetic delivery failure'; end if; return new; end $fail$;
create trigger phase5_fixture_failure before insert on public.notifications for each row execute function pg_temp.reject_fixture_notification();
select private.deliver_due_plan_reminders(100);
select private.deliver_due_plan_reminders(100);
do $retry$ begin for i in 1..4 loop update public.plan_reminders set next_attempt_at=now() where plan_id='52000000-0000-4000-8000-000000000001';perform private.deliver_due_plan_reminders(100);end loop;end $retry$;
drop trigger phase5_fixture_failure on public.notifications;
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
reset role;
update public.couple_memberships set left_at=now() where user_id='50000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
reset role;
select result from plan_tap_results;
rollback;
